export class Cpt4TaxonomyService {
  public static findByCode(cptCode: string): MasterTaxonomyProcedure | undefined {
    return CPT4_COMPREHENSIVE_REGISTRY.find((p) => p.cptCode === cptCode.trim());
  }

  public static searchByCategory(cat: string): MasterTaxonomyProcedure[] {
    return CPT4_COMPREHENSIVE_REGISTRY.filter((p) => p.category === cat || p.subCategory.includes(cat));
  }
}
